import fs from 'node:fs/promises';
import path from 'node:path';
import { env } from '../../config/env.js';

// Resolved from the server/ folder, not from wherever `node` was started, so files always land in one place.
const root = path.resolve(import.meta.dirname, '../../..', env.UPLOAD_DIR);

// Keys are always generated by us ("originals/<uuid>.jpg"), never taken from user input,
// so a file name like "../../index.js" can't escape the folder.
const fullPath = (key) => path.join(root, key);

// Files on this machine's disk. Phase 4 adds an R2 version with the same three methods.
export default {
  root,

  async save(key, buffer) {
    await fs.mkdir(path.dirname(fullPath(key)), { recursive: true });
    await fs.writeFile(fullPath(key), buffer);
  },

  get: (key) => fs.readFile(fullPath(key)),

  // force: true → removing a file that's already gone is not an error, so cleanup can safely run twice.
  remove: (key) => fs.rm(fullPath(key), { force: true }),
};
